// ===============================
// SAFE INPUT
// ===============================
const body = $json.body || {};
const data = $json.output || $json;

// -------------------------------
// QUOTATION NUMBER (SAFE)
// -------------------------------
const quotation_no =
  data.quotation_no ||
  body.quotation_no ||
  '';

// -------------------------------
// ITEMS
// -------------------------------
const rawItems = Array.isArray(data.items) ? data.items : [];

const items = rawItems.map((i, idx) => {
  const quantity = Number(i.quantity) || 1;
  const rate = Number(i.rate) || 0;
  const discount = Number(i.discount) || 0;
  const unit = i.unit || 'Nos';
  const description = i.description || '';   // ✅ ADDED (SAFE)

  let amount = quantity * rate;

  // percentage discount
  if (discount > 0 && discount <= 100) {
    amount -= (amount * discount) / 100;
  }

  // flat discount
  if (discount > 100) {
    amount -= discount;
  }

  amount = Math.max(0, Math.round(amount));

  return {
    sr: idx + 1,
    item: i.item || `Item ${idx + 1}`,
    description,               // ✅ ADDED
    quantity,
    unit,
    rate,
    discount,
    amount
  };
});

// -------------------------------
// TOTALS
// -------------------------------
const subtotal = items.reduce((s, i) => s + i.amount, 0);

const cgstPercent = Number(data.cgstPercent || body.cgst || 0);
const sgstPercent = Number(data.sgstPercent || body.sgst || 0);

const cgstAmount = Math.round(subtotal * cgstPercent / 100);
const sgstAmount = Math.round(subtotal * sgstPercent / 100);

const total = subtotal + cgstAmount + sgstAmount;

// -------------------------------
// BUILD ITEM ROWS HTML
// -------------------------------
let items_html = '';

items.forEach(i => {
  items_html += `
    <tr>
      <td class="center">${i.sr}</td>
      <td>
        <strong>${i.item}</strong>
        ${i.description ? `<br><small style="color:#555;">${i.description}</small>` : ''}
      </td>
      <td class="center">${i.quantity}</td>
      <td class="center">${i.unit}</td>
      <td class="right">₹ ${i.rate}</td>
      <td class="center">${i.discount > 0 ? i.discount + '%' : '-'}</td>
      <td class="right">₹ ${i.amount}</td>
    </tr>
  `;
});

// -------------------------------
// OPTIONAL CUSTOMER GSTIN
// -------------------------------
const customerGstinRaw = (body.customer_gstin || '').trim();
const customer_gstin = customerGstinRaw
  ? `GSTIN: ${customerGstinRaw}`
  : '';

// -------------------------------
// FINAL OUTPUT
// -------------------------------
return [
  {
    json: {
      quotation_no,              // ✅ SAFE QUOTATION NUMBER
      date: body.date,
      customer_name: body.customer_name,
      customer_email: body.customer_email,
      phone_no: body.phone_no,
      customer_gstin,
      terms: body.term_n_condition,

      items_html,

      subtotal,
      cgstPercent,
      cgstAmount,
      sgstPercent,
      sgstAmount,
      total
    }
  }
];

let html = $json.items_html;

if (!html) {
  throw new Error('items_html missing');
}

// Normalize escaped & real newlines
html = html
  .replace(/\\n/g, '')
  .replace(/\n/g, '')
  .replace(/\s+/g, ' ')
  .trim();

// Extract rows
const rows = html.match(/<tr[^>]*>.*?<\/tr>/gi) || [];

const cleanText = (str) =>
  str.replace(/<[^>]*>/g, '').replace(/\s+/g, ' ').trim();

// Extract numbers safely (handles ₹, commas, spaces)
const toNumber = (str) =>
  Number(str.replace(/[^0-9.]/g, ''));

const items = [];

for (const row of rows) {
  const cols = row.match(/<td[^>]*>.*?<\/td>/gi);
  if (!cols || cols.length < 7) continue;

  const values = cols.map(c => cleanText(c));

  // Structure after description support:
  // 0 index
  // 1 item name + optional description
  // 2 qty
  // 3 unit
  // 4 rate
  // 5 discount
  // 6 amount

  const rawItemCell = values[1] || '';
  const lines = rawItemCell.split('  ');

  const name = lines[0];
  const description = lines.slice(1).join(' ').trim() || '';

  const qty = toNumber(values[2]);
  const rate = toNumber(values[4]);

  if (!name || isNaN(qty) || isNaN(rate)) continue;

  items.push({
    item: name,
    description,       // ✅ ADDED
    quantity: qty,
    rate
  });
}

if (items.length === 0) {
  throw new Error('No items parsed from items_html');
}

return [{
  json: {
    ...$json,

    items: JSON.stringify(items),
    subtotal: $json.subtotal,
    total_tax: ($json.cgstAmount || 0) + ($json.sgstAmount || 0),
    currency: 'INR',
    invoice_status: 'sent',
    payment_status: 'unpaid',
    created_at: new Date().toISOString(),
    updated_at: new Date().toISOString()
  }
}];

