const rawItems = Array.isArray(data.items) ? data.items : [];

const items = rawItems.map((i, idx) => {
  const quantity = Number(i.quantity) || 1;
  const rate = Number(i.rate) || 0;
  const discount = Number(i.discount) || 0;
  const unit = i.unit || 'Nos';

  let amount = quantity * rate;

  // percentage discount
  if (discount > 0 && discount <= 100) {
    amount -= (amount * discount) / 100;
  }

  // flat discount
  if (discount > 100) {
    amount -= discount;
  }

  amount = Math.max(0, Math.round(amount));

  return {
    sr: idx + 1,
    item: i.item || `Item ${idx + 1}`,
    description: i.description || '',   // ✅ already added
    quantity,
    unit,
    rate,
    discount,
    amount
  };
});

// -------------------------------
// TOTALS
// -------------------------------
const subtotal = items.reduce((s, i) => s + i.amount, 0);

// FIX: handle "9%" safely
const parsePercent = v =>
  Number(String(v || '').replace('%', '')) || 0;

const cgstPercent = parsePercent(data.cgstPercent || data.cgst);
const sgstPercent = parsePercent(data.sgstPercent || data.sgst);

const cgstAmount = Math.round(subtotal * cgstPercent / 100);
const sgstAmount = Math.round(subtotal * sgstPercent / 100);

const total = subtotal + cgstAmount + sgstAmount;

// -------------------------------
// AMOUNT PAID & AMOUNT DUE (NEW - SAFE)
// -------------------------------
const amount_paid_raw =
  data.amount_paid ?? body.amount_paid ?? 0;

const amount_paid = Math.max(0, Number(amount_paid_raw) || 0);

// prevent overpayment
const safe_amount_paid = Math.min(amount_paid, total);

// remaining balance
const amount_due = Math.max(0, total - safe_amount_paid);

// -------------------------------
// BUILD ITEM ROWS HTML
// -------------------------------
let items_html = '';

items.forEach(i => {
  items_html += `
    <tr>
      <td class="center">${i.sr}</td>
      <td>
        <strong>${i.item}</strong>
        ${i.description ? `<br><small>${i.description}</small>` : ''}
      </td>
      <td class="center">${i.quantity}</td>
      <td class="center">${i.unit}</td>
      <td class="right">₹ ${i.rate}</td>
      <td class="center">${i.discount > 0 ? i.discount + '%' : '-'}</td>
      <td class="right">₹ ${i.amount}</td>
    </tr>
  `;
});

// -------------------------------
// FINAL OUTPUT (LLM FIRST, BODY FALLBACK)
// -------------------------------
return [
  {
    json: {
      invoice_no: data.invoice_no || body.invoice_no,
      date: data.date || body.date,

      customer_name: data.customer_name || body.customer_name,
      customer_email: data.customer_email || body.customer_email,
      phone_no: data.phone_no || body.phone_no,
      Gst_No: data.Gst_No || body.Gst_No,

      description: data.description || body.discription,
      term_n_condition: data.term_n_condition || body.term_n_condition,
      remark: data.remark || body.remark,

      // ✅ PAYMENT INFO
      payment_status,
      payment_method,

      // ✅ NEW PAYMENT AMOUNT SYSTEM
      amount_paid: safe_amount_paid,
      amount_due,

      items_html,

      subtotal,
      cgstPercent,
      cgstAmount,
      sgstPercent,
      sgstAmount,
      total,

      edit
    }
  }
];

let html = $json.items_html;

if (!html) {
  throw new Error('items_html missing');
}

// -------------------------------
// SAFE INVOICE NUMBER (PASS THROUGH)
// -------------------------------
const invoice_no =
  $json.invoice_no ||
  ($json.body && $json.body.invoice_no) ||
  '';

// -------------------------------
// PAYMENT INFO (PASS THROUGH)
// -------------------------------
const payment_status =
  $json.payment_status ||
  ($json.body && $json.body.payment_status) ||
  '';

const payment_method =
  $json.payment_method ||
  ($json.body && $json.body.payment_method) ||
  '';

// Normalize escaped & real newlines
html = html
  .replace(/\\n/g, '')
  .replace(/\n/g, '')
  .replace(/\s+/g, ' ')
  .trim();

// Extract rows
const rows = html.match(/<tr[^>]*>.*?<\/tr>/gi) || [];

const cleanText = (str) =>
  str.replace(/<[^>]*>/g, '').replace(/\s+/g, ' ').trim();

// Extract numbers safely (handles ₹, commas, spaces)
const toNumber = (str) =>
  Number(str.replace(/[^0-9.]/g, ''));

const items = [];

for (const row of rows) {
  const cols = row.match(/<td[^>]*>.*?<\/td>/gi);
  if (!cols || cols.length < 7) continue;

  const values = cols.map(c => cleanText(c));

  // Structure:
  // 0 index | 1 name (+ description) | 2 qty | 3 unit | 4 rate | 5 dash | 6 line total

  const name = values[1];
  const qty = toNumber(values[2]);
  const rate = toNumber(values[4]);

  if (!name || isNaN(qty) || isNaN(rate)) continue;

  items.push({
    item: name,
    quantity: qty,
    rate
  });
}

if (items.length === 0) {
  throw new Error('No items parsed from items_html');
}

return [{
  json: {
    ...$json,

    // ✅ SAFE PASSTHROUGH FIELDS
    invoice_no,
    payment_status,
    payment_method,

    items: JSON.stringify(items),
    subtotal: $json.subtotal,
    total_tax: ($json.cgstAmount || 0) + ($json.sgstAmount || 0),
    currency: 'INR',
    invoice_status: 'sent',

    created_at: new Date().toISOString(),
    updated_at: new Date().toISOString()
  }
}];

