// ===============================
// SAFE INPUT
// ===============================
const body = $json.body || {};
const data = $json.output || $json;

// -------------------------------
// EDIT INSTRUCTION
// -------------------------------
const edit =
  typeof data.edit === 'string' && data.edit.trim()
    ? data.edit.trim()
    : '';

// -------------------------------
// PAYMENT INFO (SAFE)
// -------------------------------
const payment_status =
  data.payment_status || body.payment_status || '';

const payment_method =
  data.payment_method || body.payment_method || '';

// -------------------------------
// EXPENSE BASE AMOUNT
// -------------------------------
const expense_amount_raw =
  data.expense_amount ?? body.expense_amount ?? 0;

const expense_amount = Math.max(0, Number(expense_amount_raw) || 0);

// -------------------------------
// GST HANDLING (SAFE)
// -------------------------------
const gst_applicable =
  data.gst_applicable || body.gst_applicable || 'No';

const parsePercent = v =>
  Number(String(v || '').replace('%', '')) || 0;

const gst_percent =
  gst_applicable === 'Yes'
    ? parsePercent(data.gst_percent || body.gst_percent)
    : 0;

const gst_amount = Math.round((expense_amount * gst_percent) / 100);

// -------------------------------
// TOTAL
// -------------------------------
const total_amount = expense_amount + gst_amount;

// -------------------------------
// AMOUNT PAID & AMOUNT DUE (SAFE)
// -------------------------------
const amount_paid_raw =
  data.amount_paid ?? body.amount_paid ?? 0;

const amount_paid = Math.max(0, Number(amount_paid_raw) || 0);

// prevent overpayment
const safe_amount_paid = Math.min(amount_paid, total_amount);

// remaining balance
const amount_due = Math.max(0, total_amount - safe_amount_paid);

// -------------------------------
// FINAL OUTPUT
// -------------------------------
return [
  {
    json: {
      expense_id: data.expense_id || body.expense_id,
      date: data.date || body.date,
      due_date: data.due_date || body.due_date,

      expense_category: data.expense_category || body.expense_category,
      expense_description:
        data.expense_description || body.expense_description,

      vendor_name: data.vendor_name || body.vendor_name,
      vendor_phone: data.vendor_phone || body.vendor_phone,
      vendor_email: data.vendor_email || body.vendor_email,
      vendor_gst_no: data.vendor_gst_no || body.vendor_gst_no,

      expense_amount,
      gst_applicable,
      gst_percent,
      gst_amount,
      total_amount,

      // PAYMENT INFO
      payment_status,
      payment_method,
      amount_paid: safe_amount_paid,
      amount_due,

      // FIXED ACCOUNTING FIELDS
      source_type: 'Expense',
      direction: 'OUT',

      edit
    }
  }
];

